    R = len(grid)
    C = len(grid[0]) if R > 0 else 0

    # Initialize with background
    output = [[bg] * C for _ in range(R)]

    # For each active value (non-background):
    #   1s become 0, but produce patterns
    #   0,5,7,8 preserve themselves AND produce patterns
    for r in range(R):
        for c in range(C):
            val = grid[r][c]
            if val != bg:
                # Always produce the four patterns
                for (dr, dc, write_val) in [(-1, 0, 8), (-1, 1, 5), (1, -1, 0), (1, 0, 7)]:
                    tr, tc = r + dr, c + dc
                    if 0 <= tr < R and 0 <= tc < C:
                        if output[tr][tc] == bg:
                            output[tr][tc] = write_val

                # Handle special case for 1s: they become 0
                if val == 1:
                    if output[r][c] == bg:
                        output[r][c] = 0
                else:
                    # Preserve 0,5,7,8
                    if output[r][c] == bg:
                        output[r][c] = val

    return output

